	unsigned char chunk[64];

	ptr = data;

	a = ctx->a;
	b = ctx->b;
	c = ctx->c;
	d = ctx->d;

	do {
		saved_a = a;
		saved_b = b;
		saved_c = c;
		saved_d = d;

		if(cli_memcpy(chunk, ptr, 64))
			return NULL;
/* Round 1 */
		STEP(F, a, b, c, d, SET(0), 0xd76aa478, 7)
